11	adam-nowak	Adam Nowak	{"time": 1765806793279, "blocks": [{"id": "AhRPweFplx", "data": {"text": "Adam Nowak is a professional voice actor specializing in technology and business audiobooks. With over a decade of experience, Adam brings clarity and energy to complex topics."}, "type": "paragraph"}, {"id": "nM3-qFsHtD", "data": {"text": "Highlights:"}, "type": "paragraph"}, {"id": "2iCT3uMUHE", "data": {"items": ["Narrated over 50 audiobooks on tech and enterprise", "Voice recognized for warm, engaging, and authoritative tone", "Works with global publishers and indie authors"], "style": "unordered"}, "type": "list"}], "version": "2.30.7"}	2025-12-01 15:48:42+00	t	2025-12-01 15:48:42+00			{}	{}	7	t	\N
12	john-murphy	John Murphy	{"time": 1765806805063, "blocks": [{"id": "MrUpszZr_W", "data": {"text": "John Murphy narrates business and e-commerce audiobooks with precision and storytelling flair. He helps bring real-world brand experiences to life."}, "type": "paragraph"}, {"id": "5SibraMZ1A", "data": {"text": "Highlights:"}, "type": "paragraph"}, {"id": "RrhzU-S1Af", "data": {"items": ["Specialized in retail and scaling businesses", "Collaborates with top brands for authentic narration", "Skilled in balancing technical info with engaging storytelling"], "style": "unordered"}, "type": "list"}], "version": "2.30.7"}	2025-12-01 15:50:23+00	t	2025-12-01 15:50:23+00			{}	{}	7	t	\N
